let i = 0;
let cnt = 1; // subtotal Column 호출 수
scwin.gridView1_subtotalStyleFormatter = function(value, formattedValue, subtotalColumnId) {
	if (subtotalColumnId !== "column13" && subtotalColumnId !== "column11") {
		return "w2subtotaldefault";
	}
	const str = gridView1._getExcelSubtotalData(); // subtotal 값 전체 문자열
	const resultArray = str.replace(/"/g, '').split(',').map(val => val === '' ? '' : Number(val));
	// subtotal 행별 5개(Column 수)씩, column13·column11 두 번 호출마다 다음 행
	const group = resultArray.slice(i, i + 5);
	if (cnt > 1 && cnt % 2 == 1) {
		i = i + 5;
	}
	if (group.length === 0) {
		return; // 원본과 같게 빈 그룹은 class 미지정·cnt 유지
	}
	cnt++;
	return Math.max(...group) === value ? "w2subtotalplus" : "w2subtotalminus";
};

scwin.trigger3_onclick = function(e) {
	var jsnOptions = {
		useSubTotal: "true",
		useSubTotalData: "true",
		useStyle: "true",
		useClass: "true",
		fileName: "wese_1163.xlsx",
		useSubTotalColumnClass: "true"
	};
	gridView1.advancedExcelDownload(jsnOptions);
};
